    FocusTimerTest.Run(root);DriveProtocolTest.Run(root);File.WriteAllText(result,"PASS: attachments (local, team folder, members, safe names); notification registry (unique kinds, defaults, per-kind and master switches); team notifications (new, assigned, own, once, join); shared network projects (members, assignment, privacy, propagation, guards, rename, disconnect); smart assignee; smart quick-add parsing; per-context task layout persistence; project rename layout; focus start/pause/reset/restart; focus/break transition; palette persistence; Drive API protocol (mock); persistence; restart; validation; sync; conflicts; history; deletion; import/export; offline writes; empty projects; project rename/removal; kanban state; theme; PKCE standard vector; encrypted OAuth configuration; immutable cloud identities. Live Google authorization requires registered OAuth client.\r\n",Encoding.UTF8);return 0;
